import type { Annotation, AnnotationMap, Rect } from "./types";
import { hexToRgb, openMupdf, saveMupdf, transformPoint, type Matrix } from "../mupdf/loader";

/**
 * Writes editable annotations into the PDF as genuine PDF annotations (with
 * appearance streams generated by MuPDF, so every PDF reader displays them).
 *
 * Each written annotation also carries its editable model as JSON under the
 * private key /MarmaraData, so reopening the file in Marmara PDF restores
 * fully editable annotations (see importAnnotations).
 */

export const MARMARA_KEY = "MarmaraData";

type MDoc = import("mupdf").PDFDocument;
type MPage = import("mupdf").PDFPage;
type MuPDF = typeof import("mupdf");

function dataUrlToBytes(dataUrl: string): Uint8Array {
  const b64 = dataUrl.slice(dataUrl.indexOf(",") + 1);
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function rectToPage(ctm: Matrix, r: Rect): [number, number, number, number] {
  const [ax, ay] = transformPoint(ctm, r[0], r[1]);
  const [bx, by] = transformPoint(ctm, r[2], r[3]);
  return [Math.min(ax, bx), Math.min(ay, by), Math.max(ax, bx), Math.max(ay, by)];
}

/** Quad (UL, UR, LL, LR) in MuPDF page space for a PDF-space rect. */
function rectToQuad(ctm: Matrix, r: Rect): number[] {
  return [
    ...transformPoint(ctm, r[0], r[3]),
    ...transformPoint(ctm, r[2], r[3]),
    ...transformPoint(ctm, r[0], r[1]),
    ...transformPoint(ctm, r[2], r[1]),
  ];
}

function writeOne(mupdf: MuPDF, doc: MDoc, page: MPage, ctm: Matrix, a: Annotation) {
  const p = (x: number, y: number) => transformPoint(ctm, x, y);
  let annot: import("mupdf").PDFAnnotation;
  switch (a.type) {
    case "highlight":
    case "underline":
    case "strikeout": {
      annot = page.createAnnotation(a.type === "highlight" ? "Highlight" : a.type === "underline" ? "Underline" : "StrikeOut");
      annot.setQuadPoints(a.rects.map((r) => rectToQuad(ctm, r)) as never);
      break;
    }
    case "ink": {
      annot = page.createAnnotation("Ink");
      annot.setInkList(a.paths.map((path) => path.map(([x, y]) => p(x, y))) as never);
      annot.setBorderWidth(a.width);
      break;
    }
    case "rect":
    case "ellipse": {
      annot = page.createAnnotation(a.type === "rect" ? "Square" : "Circle");
      annot.setRect(rectToPage(ctm, a.rect));
      annot.setBorderWidth(a.width);
      if (a.fill) annot.setInteriorColor(hexToRgb(a.fill));
      break;
    }
    case "line":
    case "arrow": {
      annot = page.createAnnotation("Line");
      annot.setLine(p(...a.from), p(...a.to));
      annot.setBorderWidth(a.width);
      if (a.type === "arrow") annot.setLineEndingStyles("None", "OpenArrow");
      break;
    }
    case "freetext": {
      annot = page.createAnnotation("FreeText");
      annot.setRect(rectToPage(ctm, a.rect));
      annot.setDefaultAppearance("Helv", a.fontSize, hexToRgb(a.color));
      annot.setContents(a.text);
      annot.setBorderWidth(0);
      break;
    }
    case "note": {
      annot = page.createAnnotation("Text");
      const [x, y] = p(a.point[0], a.point[1]);
      annot.setRect([x, y, x + 20, y + 20]);
      annot.setIcon("Comment");
      annot.setContents(a.text);
      break;
    }
    case "signature":
    case "image": {
      annot = page.createAnnotation("Stamp");
      annot.setRect(rectToPage(ctm, a.rect));
      annot.setIntent("StampImage");
      annot.setStampImage(new mupdf.Image(dataUrlToBytes(a.dataUrl)));
      break;
    }
  }
  if (a.type !== "freetext" && a.type !== "signature" && a.type !== "image") annot.setColor(hexToRgb(a.color));
  if (a.opacity < 1) annot.setOpacity(a.opacity);
  if (a.type !== "note" && a.type !== "freetext" && a.comment) annot.setContents(a.comment);
  if (a.author) annot.setAuthor(a.author);
  annot.setCreationDate(new Date(a.createdAt));
  annot.setModificationDate(new Date());
  annot.setName(`marmara-${a.id}`);
  annot.getObject().put(MARMARA_KEY, doc.newString(JSON.stringify(a)));
  annot.update();
}

export async function bakeAnnotations(
  bytes: Uint8Array,
  pageIds: string[],
  annotations: AnnotationMap,
  incremental = false,
): Promise<Uint8Array> {
  const { mupdf, doc } = await openMupdf(bytes);
  try {
    pageIds.forEach((id, i) => {
      const list = annotations[id];
      if (!list?.length) return;
      const page = doc.loadPage(i) as MPage;
      const ctm = page.getTransform() as Matrix;
      for (const a of list) {
        try {
          writeOne(mupdf, doc, page, ctm, a);
        } catch (e) {
          console.error("Failed to write annotation", a.type, e);
          throw new Error(`Could not save a ${a.type} annotation on page ${i + 1}: ${(e as Error).message}`);
        }
      }
      page.update();
    });
    return saveMupdf(doc, incremental && doc.canBeSavedIncrementally() ? "incremental" : "compress");
  } finally {
    doc.destroy();
  }
}

/**
 * Extracts annotations previously written by Marmara PDF, returning them as
 * editable objects and the PDF bytes without them. Other annotations are left
 * untouched (they are still displayed by the renderer).
 */
export async function importAnnotations(
  bytes: Uint8Array,
  pageIds: string[],
  password?: string,
): Promise<{ bytes: Uint8Array; annotations: AnnotationMap; count: number } | null> {
  const { doc } = await openMupdf(bytes, password);
  try {
    const annotations: AnnotationMap = {};
    let count = 0;
    const n = doc.countPages();
    for (let i = 0; i < n && i < pageIds.length; i++) {
      const page = doc.loadPage(i) as MPage;
      const found: Annotation[] = [];
      for (const annot of [...page.getAnnotations()]) {
        const data = annot.getObject().get(MARMARA_KEY);
        if (!data.isString()) continue;
        try {
          const a = JSON.parse(data.asString()) as Annotation;
          if (!a || typeof a.type !== "string" || typeof a.id !== "string") continue;
          // Contents may have been edited in another PDF app: keep them in sync.
          if (a.type === "note" || a.type === "freetext") a.text = annot.getContents() || a.text;
          found.push(a);
          page.deleteAnnotation(annot);
        } catch {
          /* not ours / malformed: leave it */
        }
      }
      if (found.length) {
        page.update();
        annotations[pageIds[i]] = found;
        count += found.length;
      }
    }
    if (!count) return null;
    return { bytes: saveMupdf(doc, password ? "compress,encrypt=keep" : "compress"), annotations, count };
  } finally {
    doc.destroy();
  }
}
